import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.Boholvbs.js";const k=JSON.parse('{"title":"Skills","description":"SKILL.md files that teach PrioriCode procedures on demand — format, discovery paths, remote skill packs, and how the model invokes skills.","frontmatter":{"title":"Skills","description":"SKILL.md files that teach PrioriCode procedures on demand — format, discovery paths, remote skill packs, and how the model invokes skills."},"headers":[],"relativePath":"extending/skills.md","filePath":"extending/skills.md"}'),n={name:"extending/skills.md"};function l(o,s,h,d,r,p){return i(),t("div",null,[...s[0]||(s[0]=[a(`<p>A skill is a folder with a <code>SKILL.md</code> inside: instructions for one procedure, loaded <em>when needed</em> instead of permanently bloating every prompt. It&#39;s the difference between a poster on the wall and a laminated card the agent pulls out for the job.</p><h2 id="the-format" tabindex="-1">The format <a class="header-anchor" href="#the-format" aria-label="Permalink to &quot;The format&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.prioricode/skills/release-checklist/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>├── changelog-template.md      ← sibling files: resources the skill points at</span></span>
<span class="line"><span>└── scripts/verify.sh</span></span></code></pre></div><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: release-checklist</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Run the pre-release checklist for this repo — lint, typecheck, smoke-test, changelog.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Release checklist</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Run </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`bun run lint\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`bun run typecheck\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; stop on failure and report which one broke.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Start </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`bun run dev\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, exercise the changed flow, paste what you saw.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Draft the changelog entry using [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">changelog-template.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">changelog-template.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) — read it with the Read tool.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never push to main yourself; leave that human.</span></span></code></pre></div><p>Only two frontmatter fields are recognized: <code>name</code> (required) and <code>description</code>. The <strong>description is the advertisement</strong> — every skill&#39;s name+description lands in the system prompt, and the model decides from that one line whether to load the body. Make it say <em>when to use</em>, not just <em>what it is</em> (this repo&#39;s own skills are written that way; inspect <code>~/.local/share/prioricode</code> equivalents with <code>/skills</code>).</p><p>The body becomes the loaded content, delivered with the skill&#39;s directory and a sampled file list, so relative references (<code>changelog-template.md</code>) resolve for the agent.</p><h2 id="where-skills-are-found" tabindex="-1">Where skills are found <a class="header-anchor" href="#where-skills-are-found" aria-label="Permalink to &quot;Where skills are found&quot;">​</a></h2><p>Scanned at startup, in this order:</p><ol><li><code>~/.claude/skills/**/SKILL.md</code> and <code>~/.agents/skills/**/SKILL.md</code> — external skill homes, so skills from other agent ecosystems just work. Turn them off with <code>PRIORICODE_DISABLE_EXTERNAL_SKILLS=1</code> (or the broader <code>PRIORICODE_DISABLE_CLAUDE_CODE=1</code>).</li><li>Every PrioriCode config directory — <code>~/.config/prioricode</code>, <code>~/.prioricode</code>, and <code>.prioricode/</code> from your cwd up to the worktree root — under <code>{skill,skills}/**/SKILL.md</code>.</li><li>Extra paths from config:</li></ol><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;paths&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;../shared-skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/work/skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } }</span></span></code></pre></div><ol start="4"><li>Remote packs: <code>skills.urls</code> —</li></ol><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;urls&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://skills.example.com/acme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } }</span></span></code></pre></div><p>Each URL must serve <code>index.json</code> shaped as <code>{ &quot;skills&quot;: [{ &quot;name&quot;, &quot;files&quot;: [&quot;SKILL.md&quot;, …], &quot;version&quot;? }] }</code>. Files are cached under the cache dir with atomic version-swaps, so an updated pack lands whole or not at all.</p><p>Duplicate names: last one wins and you get a warning — intentional, project skills override global ones. A built-in skill (<code>customize-prioricode</code>, for editing PrioriCode&#39;s own config) ships with the binary and can be overridden on disk.</p><h2 id="using-them" tabindex="-1">Using them <a class="header-anchor" href="#using-them" aria-label="Permalink to &quot;Using them&quot;">​</a></h2><ul><li><strong><code>/skills</code></strong> in the TUI lists discovered skills and inserts the chosen one into your prompt.</li><li><strong>The model loads them itself</strong> via the <code>skill</code> tool when a task matches a description — the tool injects that skill&#39;s full body into the conversation.</li><li><strong>Permissions:</strong> skill loading asks under the <code>skill</code> permission with the skill name as pattern — <code>&quot;skill&quot;: { &quot;my-*&quot;: &quot;allow&quot;, &quot;*&quot;: &quot;ask&quot; }</code> tunes the noise.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Skill bodies can include shell snippets as <em>instructions</em>, but the skill file itself is just prompt material — it runs nothing. Anything executable happens because the agent decides to run it, which means it still passes through <a href="./../using/permissions.html">permissions</a>. That&#39;s by design.</p></div><h2 id="skills-vs-commands-vs-agents" tabindex="-1">Skills vs commands vs agents <a class="header-anchor" href="#skills-vs-commands-vs-agents" aria-label="Permalink to &quot;Skills vs commands vs agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Want</th><th>Build</th></tr></thead><tbody><tr><td>The agent should know <em>how</em> to do procedure X when relevant</td><td>skill</td></tr><tr><td><em>You</em> want to trigger a canned prompt by name</td><td><a href="./commands.html">custom command</a></td></tr><tr><td>A whole different persona with its own tools/model</td><td><a href="./../using/agents.html">custom agent</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../using/context.html">Context</a> — AGENTS.md vs skills: standing knowledge vs on-demand procedures. <ul><li><a href="./../reference/config.html">Config reference</a> — <code>skills.paths</code> / <code>skills.urls</code>.</li><li><a href="./../reference/tools.html">Tools reference</a> — The <code>skill</code> tool contract.</li></ul></li></ul>`,21)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
